const s=$getWorkflowStaticData('global'); const raw=Array.isArray($json.data)?$json.data:[];
const now=Date.now(); s.mode='LIVE_ASSIST'; s.lastScanAt=new Date().toISOString();
if(raw.length<20) return [{json:{proposalCreated:false,reason:'NO_CANDLES'}}];
const c=raw.slice().reverse().map(x=>Number(x[4])).filter(x=>Number.isFinite(x)&&x>0);
const sma=n=>c.slice(-n).reduce((a,b)=>a+b,0)/n; const f=sma(5), slow=sma(20), last=c.at(-1), prev=c.at(-2);
let g=0,l=0; for(let i=Math.max(1,c.length-14);i<c.length;i++){let d=c[i]-c[i-1]; if(d>0)g+=d; else l-=d;}
const rs=l===0?100:(g/14)/(l/14); const rsi=100-(100/(1+rs)); const mom=(last-prev)/prev;
s.lastMarket={at:s.lastScanAt,pair:'BTC-USDT',last,sma5:f,sma20:slow,rsi,momentum:mom,marketOk:true};
if(s.pendingTrade?.status==='pending' && now<Number(s.pendingTrade.expiresAt||0)) return [{json:{proposalCreated:false,reason:'PENDING_EXISTS'}}];
if(s.pendingTrade?.status==='pending') s.pendingTrade.status='expired';
let side=null, amount=5, reason='', confidence=.7;
if(!s.position && f>slow*1.001 && mom>0.001 && rsi>=52 && rsi<=68){side='buy'; const conf=Math.min(.95,.66+(f/slow-1)*25+mom*18); amount=conf>=.80?10:5; reason='Bullish 15m · RSI '+rsi.toFixed(1)+' · momentum '+(mom*100).toFixed(2)+'%'; confidence=Number(conf.toFixed(2));}
if(s.position && (last<=s.position.stopLoss || last>=s.position.takeProfit || f<slow*.999 || rsi<45)){side='sell'; amount=Number(s.position.amountQuote||5); reason=last<=s.position.stopLoss?'Stop loss':last>=s.position.takeProfit?'Take profit':'Exit signal · RSI '+rsi.toFixed(1); confidence=.78;}
if(!side) return [{json:{proposalCreated:false,reason:'NO_SIGNAL',last,rsi,sma5:f,sma20:slow}}];
const p={id:'J'+now+(side==='buy'?'B':'S'),side,pair:'BTC-USDT',amountQuote:Math.min(10,Math.max(5,amount)),entry:last,stopLoss:side==='buy'?Number((last*.985).toFixed(2)):Number(s.position?.stopLoss||0),takeProfit:side==='buy'?Number((last*1.03).toFixed(2)):Number(s.position?.takeProfit||0),confidence,reason,createdAt:now,expiresAt:now+20*60*1000,status:'pending'};
s.pendingTrade=p; s.lastEvent={at:new Date().toISOString(),message:side.toUpperCase()+' proposal BTC-USDT'};
return [{json:{proposalCreated:true,proposal:p}}];

